// Build constants: Wi lanes per batch, bytes per complex element, vec and waste in lanes.
template<typename T>
struct env {
    static constexpr std::size_t Wi = build_width<T>;
    static constexpr double W = double(Wi);
    static constexpr double bytes = 2.0 * double(sizeof(T));
    static constexpr double vec(std::size_t m) { return double((m + Wi - 1) / Wi); }
    static constexpr double waste(std::size_t m) { return (vec(m) * W - double(m)) / W; }
};

template<typename T>
[[nodiscard]] constexpr double chain_work(std::size_t n) {
    return admiral::detail::chain_work(n, env<T>::Wi, build_vector_regs);
}

// Appends the three features every form shares: log2(lanes), ln(bytes per element), clang flag.
template<typename T, std::size_t K>
[[nodiscard]] constexpr std::array<double, K + 3> with_tail(const std::array<double, K>& a) {
    std::array<double, K + 3> f{};
    for (std::size_t i = 0; i < K; ++i) f[i] = a[i];
    f[K]     = ct_log2(env<T>::W);
    f[K + 1] = ct_log2(env<T>::bytes) / ct_log2(2.7182818284590452354);
    f[K + 2] = build_compiler == "clang" ? 1.0 : 0.0;
    return f;
}

