using forms = std::tuple<codelet, iterative_dif, good_thomas, four_step, rader, bluestein>;
inline constexpr std::size_t NFORM = std::tuple_size_v<forms>;

// Predicted ln(cycles) for form M at length n: bias + w . features.
template<typename M, typename T>
[[nodiscard]] constexpr double score(std::size_t n) {
    const auto x = M::template features<T>(n);
    static_assert(std::tuple_size_v<admiral::detail::remove_cvref_t<decltype(x)>> ==
                  std::tuple_size_v<admiral::detail::remove_cvref_t<decltype(M::w)>>,
                  "feature/coefficient count mismatch");
    double acc = M::bias;
    for (std::size_t i = 0; i < x.size(); ++i) acc += M::w[i] * x[i];
    return acc;
}

template<typename T, std::size_t... I>
[[nodiscard]] constexpr auto score_all(std::size_t n, std::index_sequence<I...>) {
    return std::array<double, sizeof...(I)>{score<std::tuple_element_t<I, forms>, T>(n)...};
}

template<std::size_t... I>
[[nodiscard]] constexpr auto tags(std::index_sequence<I...>) {
    return std::array<base_form, sizeof...(I)>{std::tuple_element_t<I, forms>::tag...};
}

