struct base_model_ranking {
    std::array<base_form, base_model::NFORM> form{};
    std::array<float, base_model::NFORM> log_cyc{};
    std::size_t count = 0;
    float best_cyc = -1.f;
};

[[nodiscard]] constexpr const char* base_form_name(base_form f) noexcept {
    switch (f) {
    case base_form::codelet:           return "codelet";
    case base_form::iterative_dif:     return "iterative_dif";
    case base_form::good_thomas:       return "good_thomas";
    case base_form::four_step:         return "four_step";
    case base_form::four_step_batched: return "four_step_batched";
    case base_form::rader:             return "rader";
    case base_form::bluestein:         return "bluestein";
    }
    return "?";
}

// Every form scored at n, cheapest first. best_cyc is exp() of the winner, so it is in cycles.
template<typename T>
[[nodiscard]] constexpr base_model_ranking score_ranking(std::size_t n) {
    using namespace base_model;
    base_model_ranking out;
    if (n < BASE_MODEL_NMIN || n > BASE_MODEL_NMAX) return out;

    constexpr auto seq = std::make_index_sequence<NFORM>{};
    const auto z = score_all<T>(n, seq);
    constexpr auto tag = tags(seq);

    std::array<bool, NFORM> used{};
    for (std::size_t k = 0; k < NFORM; ++k) {
        std::size_t bi = NFORM;
        for (std::size_t f = 0; f < NFORM; ++f)
            if (!used[f] && (bi == NFORM || z[f] < z[bi])) bi = f;
        used[bi] = true;
        out.form[k] = tag[bi];
        out.log_cyc[k] = float(z[bi]);
        if (k == 0) out.best_cyc = float(ct_exp(z[bi]));
    }
    out.count = NFORM;
    return out;
}

// score_ranking memoized for 2..512 in a function-local static table.
template<typename T>
[[nodiscard]] inline const base_model_ranking& base_route_ranking(std::size_t n) {
    static const std::array<base_model_ranking, BASE_MODEL_NMAX + 1> table = [] {
        std::array<base_model_ranking, BASE_MODEL_NMAX + 1> t{};
        for (std::size_t i = BASE_MODEL_NMIN; i <= BASE_MODEL_NMAX; ++i) t[i] = score_ranking<T>(i);
        return t;
    }();
    return table[n <= BASE_MODEL_NMAX ? n : 0];
}

// The cheapest form at n and its predicted cycles; cyc is -1 outside 2..512.
template<typename T>
[[nodiscard]] inline base_cost_entry base_cost_for(std::size_t n) noexcept {
    const auto& r = base_route_ranking<T>(n);
    if (r.count == 0) return {-1.f, base_form::codelet};
    return {r.best_cyc, r.form[0]};
}

